export const schema=["CREATE TABLE `api_cache` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`fetched_at` integer NOT NULL,\n\t`data` text NOT NULL\n)","CREATE TABLE `cards` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`version` text NOT NULL,\n\t`card_key` text NOT NULL,\n\t`info` text NOT NULL,\n\t`quantity` real NOT NULL\n)","CREATE UNIQUE INDEX `cards_version_key` ON `cards` (`owner`,`version`,`card_key`)","CREATE TABLE `imports` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`mode` text NOT NULL,\n\t`filename` text NOT NULL,\n\t`headers` text NOT NULL,\n\t`expected` integer NOT NULL,\n\t`status` text NOT NULL,\n\t`created_at` integer NOT NULL\n)","CREATE TABLE `inventory_rows` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`version` text NOT NULL,\n\t`row_no` integer NOT NULL,\n\t`card_key` text NOT NULL,\n\t`info` text NOT NULL,\n\t`raw` text NOT NULL\n)","CREATE INDEX `rows_owner_version` ON `inventory_rows` (`owner`,`version`,`row_no`)","CREATE INDEX `rows_card` ON `inventory_rows` (`owner`,`version`,`card_key`)","CREATE TABLE `market` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`card_key` text NOT NULL,\n\t`product_id` text,\n\t`fetched_at` integer NOT NULL,\n\t`data` text NOT NULL,\n\t`detail` text NOT NULL\n)","CREATE UNIQUE INDEX `market_owner_card` ON `market` (`owner`,`card_key`)","CREATE TABLE `refresh_products` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`run_id` text NOT NULL,\n\t`product_id` text NOT NULL,\n\t`status` text NOT NULL\n)","CREATE TABLE `refresh_runs` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`status` text NOT NULL,\n\t`started_at` integer NOT NULL,\n\t`completed` integer DEFAULT 0 NOT NULL,\n\t`failed` integer DEFAULT 0 NOT NULL,\n\t`spent` real DEFAULT 0 NOT NULL,\n\t`total` integer NOT NULL,\n\t`detail` text NOT NULL\n)","CREATE TABLE `workspaces` (\n\t`owner` text PRIMARY KEY NOT NULL,\n\t`active_version` text,\n\t`filename` text,\n\t`headers` text DEFAULT '[]' NOT NULL,\n\t`imported_at` integer,\n\t`updated_at` integer,\n\t`settings` text DEFAULT '{}' NOT NULL,\n\t`secret` text DEFAULT '' NOT NULL,\n\t`usage` text DEFAULT '{}' NOT NULL,\n\t`import_lock` text\n)","CREATE TABLE `refresh_targets` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`run_id` text NOT NULL,\n\t`card_key` text NOT NULL\n)","CREATE TABLE `api_requests` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`account_id` text NOT NULL,\n\t`run_id` text,\n\t`path` text NOT NULL,\n\t`created_at` integer NOT NULL,\n\t`reserved` real NOT NULL,\n\t`charged` real,\n\t`status` text NOT NULL,\n\t`request_id` text,\n\t`metadata` text DEFAULT '{}' NOT NULL\n)","CREATE INDEX `requests_owner_date` ON `api_requests` (`owner`,`created_at`)","CREATE TABLE `credit_accounts` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`available` real DEFAULT 0 NOT NULL,\n\t`reserved` real DEFAULT 0 NOT NULL,\n\t`dirty` integer DEFAULT 1 NOT NULL,\n\t`period` text DEFAULT '' NOT NULL,\n\t`snapshot` text DEFAULT '{}' NOT NULL,\n\t`lock_token` text,\n\t`lock_until` integer DEFAULT 0 NOT NULL\n)","CREATE TABLE `auth_codes` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`owner` text NOT NULL,\n\t`challenge` text NOT NULL,\n\t`expires_at` integer NOT NULL\n)"];
